tb_patterns.tb_text:
module counter4_tb;
  logic clk, rst, en;
  logic [3:0] count;

  counter4 dut(.clk(clk), .rst(rst), .en(en), .count(count));

  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  initial begin
    rst = 1; en = 0;
    #10 rst = 0; en = 1;
    #50 $finish;
  end
endmodule
